诊断显示编译和 Miri 都通过，但 lockbud 报了问题。我先看具体报告和当前代码，再改同步方式。```rust
use std::sync::{Arc, Mutex};
use std::thread;

use concir_sync::Semaphore;

fn main() {
    // c 的声明范围是 0..=2，初值为 0。任何可达状态都必须满足 c <= 1。
    let m = Arc::new(Mutex::new(0i32));
    let gate = Semaphore::new(1);

    let m1 = Arc::clone(&m);
    let gate1 = Arc::clone(&gate);
    let w1 = thread::spawn(move || {
        // 信号量临界区必须在拿 m 之前结束，避免与互斥锁形成相反的加锁顺序。
        {
            let _permit = gate1.try_acquire();
        }
        let mut c = m1.lock().unwrap();
        if *c < 1 {
            *c += 1;
        }
    });

    let m2 = Arc::clone(&m);
    let gate2 = Arc::clone(&gate);
    let w2 = thread::spawn(move || {
        {
            let _permit = gate2.try_acquire();
        }
        let mut c = m2.lock().unwrap();
        if *c < 1 {
            *c += 1;
        }
    });

    w1.join().unwrap();
    w2.join().unwrap();

    let c = *m.lock().unwrap();
    println!("DONE done={c}");
}
